
IG$.p$PivotBrws = $s.extend($s.panel, {
	region:"center",
	layout: {
		type: "fit",
		align: "stretch"
	},
	
	loadSheetOption: function(sheetoption, reportoption, sheet_tree, filteroption) {
		var me = this,
			pivoteditor = me.down("[name=pivoteditor]"),
			rop,
			cobj;
		
		me.sheetoption = sheetoption;
		me.reportoption = reportoption;
		me.filteroption = filteroption;
		me._cache_tree = sheet_tree;
		
		me._init();
	},
	
	_init: function() {
		var me = this,
			rop = me.reportoption,
			custom_formula = me.down("[name=custom_formula]"),
			calculation_custom_dims = rop._mc.calculation_custom_dims, 
			dp = [], i, dim,
			meta_type = me.meta_type,
			cube_objects;

		if (!me._finit)
		{
			var cube_tree = me.down("[name=cube_tree]");
			cube_tree.on("cellclick", function(tobj, node, c, record, index, e) {
				me.fireEvent("pb_cell_click", record);
			}, me);
			cube_tree.on("itemdblclick", function(tobj, record, item, index, e, eopts) {
				me.fireEvent("pb_cell_dbclick", record);
			}, me);
			me._finit = true;
		}
		
		if (meta_type == "sql_report")
		{
			me._load_columns(rop._mc.inlineview_sql_objects);
		}
		else
		{
			cube_objects = rop._mc.cube_objects && rop._mc.cube_objects.length ? rop._mc.cube_objects : null;
			me.getCube(cube_objects);
		}
		
		if (calculation_custom_dims)
		{
			for (i=0; i < calculation_custom_dims.length; i++)
			{
				dim = calculation_custom_dims[i];
				
				dp.push({
					name: dim.name,
					uid: dim.uid,
					type: dim.type
				});
			}
		}
		
		custom_formula.store.loadData(dp);
	},
	
	_confirm: function() {
		var pivoteditor = this.down("[name=pivoteditor]");
		pivoteditor._confirm();
	},
	
	getCube: function(cobj) {
		var me = this,
			cube_tree = me.down("[name=cube_tree]"),
			p,
			i,
			c, bf = 0,
			rnode,
			citem, ritem,
			reportoption = me.reportoption,
			sheetoption = me.sheetoption,
			filteroption = me.filteroption,
			sop = sheetoption ? sheetoption.model : null,
			ds_object = sop && sop.cube_object ? sop.cube_object : null,
			_cache_tree = me._cache_tree;
		
		rnode = {
			type: "ROOT",
			name: "Cubes",
			leaf: false,
			expanded: true,
			children: [
			   {
				   type: "load",
				   name: "Loading..."
			   }
			]
		};
		
		if (!ds_object && filteroption && filteroption.model && filteroption.model.cube_object)
		{
			ds_object = filteroption.model.cube_object;
		}
		
		if (!ds_object && cobj && cobj.length)
		{
			ds_object = cobj[0];
		}
		
		if (ds_object)
		{
			rnode.uid = ds_object.uid,
			rnode.name = ds_object.name,
			rnode.nodepath = ds_object.nodepath,
			rnode.type = ds_object.type;
		}
		
		if (_cache_tree)
		{
			if (_cache_tree.uid == rnode.uid)
			{
				rnode.children = [];
				me._update_cache_tree(rnode, _cache_tree.children);
			}
			me._cache_tree = null;
		}
		
		cube_tree.setRootNode(rnode).expand();
		
		me.fireEvent("cube_changed", me);
	},
	
	_load_columns: function(inlineview_sql_objects) {
		var me = this,
			sheetoption = me.sheetoption,
			cube_tree = me.down("[name=cube_tree]"),
			p,
			i,
			c, bf = 0,
			rnode,
			citem, ritem,
			_cache_tree = me._cache_tree;
		
		rnode = {
			type: "ROOT",
			name: "Cubes",
			leaf: false,
			expanded: true,
			children: []
		};
		
		$.each(inlineview_sql_objects, function(j, sql_objects) {
			if (sheetoption && sheetoption.model.sql_id && sheetoption.model.sql_id != sql_objects.sql_id)
				return;
			
			var children = sql_objects.meta_dimensions;
			
			var tdata = {
				sql_id: sql_objects.sql_id,
				name: sql_objects.name,
				type: "InlineView",
				children: [],
				expanded: true,
				leaf: false
			};
			
			tdata.iconcls = IG$.get_metatype_icon(tdata.type.toLowerCase());
			
			rnode.children.push(tdata);
			
			$.each(children, function(i, node) {
				var ndata = me._clone(node);
				if (node.attributes && node.attributes.attrb4)
				{
					ndata.datatype = IG$.get_datatype(node.attributes.attrb4);
				}
				ndata.typename = ndata.type ? ndata.type.toLowerCase() : "";
				ndata.iconcls = IG$.get_metatype_icon(ndata.typename, ndata);
				ndata.writable = true;
				ndata.leaf = true;
				tdata.children.push(ndata);
			});
		});
		
		cube_tree.setRootNode(rnode).expand();
		
		me.fireEvent("cube_changed", me);
	},
	
	_update_cache_tree: function(rnode, children) {
		var me = this,
			i,
			ndata,
			cdata;
		
		for (i=0; i < children.length; i++)
		{
			cdata = children[i];
			ndata = me._clone(cdata);
			rnode.children.push(ndata);
			
			if (cdata.children && cdata.children.length)
			{
				ndata.expanded = true;
				ndata.children = [];
				me._update_cache_tree(ndata, cdata.children);
			}
			else if (!cdata.leaf)
			{
				ndata.children = [
				   {
					   type: "load",
					   name: "Loading..."
				   }
				];
			}
		}
	},
	
	_clone: function(cdata) {
		var ndata = {
			name: cdata.name,
			nodepath: cdata.nodepath,
			type: cdata.type,
			uid: cdata.uid,
			sql_id: cdata.sql_id,
			writable: cdata.writable,
			leaf: cdata.leaf,
			address: cdata.address,
			description: cdata.description,
			attributes: cdata.attributes,
			icon: cdata.icon,
			iconCls: cdata.iconCls,
			is_sub: cdata.is_sub,
			lfd: cdata.lfd,
			locale_name: cdata.local_name,
			ltype: cdata.ltype,
			manage: cdata.manage,
			memo: cdata.memo,
			mid: cdata.mid,
			modifier: cdata.modifier,
			objinfo: cdata.objinfo,
			owner: cdata.owner,
			pid: cdata.pid,
			revision: cdata.revision,
			sid: cdata.sid,
			text: cdata.text,
			updatedate: cdata.updatedate,
			updatedatefm: cdata.updatedatefm,
			datatype: cdata.datatype
		};
		
		return ndata;
	},
	
	createItem: function(itemtype) {
		var me = this,
			instance = me.instance,
			mpanel = instance.mainPanel,
			rop = me.reportoption,
			cube_tree = me.down("[name=cube_tree]"),
			rcube = cube_tree.getRootNode(),
			calculation_custom_dims = rop._mc.calculation_custom_dims,
			custom_formula = me.down("[name=custom_formula]");
		
		calculation_custom_dims = rop._mc.calculation_custom_dims = rop._mc.calculation_custom_dims || []; 
			
		mpanel.navigateApp(null, itemtype.toLowerCase(), "", null, true, true, {
			editmode: true,
			dmode_cnt: {
				type: itemtype
			},
			cubeuid: rcube.get("uid"),
			cubepath: rcube.get("nodepath"),
			dmode: 1,
			callback: new IG$.callBackObj(me, function(citem) {
				var kname = IG$.getKeyName(citem.name),
					kmap = {},
					kseq = 0;
				
				$.each(calculation_custom_dims, function(i, c) {
					kmap[c.uid] = 1;
				});
				
				while (kmap[kname])
				{
					kname += "_" + (kseq++);
				}
				
				citem.uid = kname;
				calculation_custom_dims.push(citem);
				
				custom_formula.store.add({
					uid: citem.uid,
					type: citem.type,
					name: citem.name
				});
			})
		});
	},
	
	editCustomItem: function(rec) {
		var me = this,
			instance = me.instance,
			mpanel = instance.mainPanel,
			rop = me.reportoption,
			cube_tree = me.down("[name=cube_tree]"),
			rcube = cube_tree.getRootNode(),
			calculation_custom_dims = rop._mc.calculation_custom_dims,
			i, duid = rec.get("uid"),
			citem;
		
		for (i=0; i < calculation_custom_dims.length; i++)
		{
			if (calculation_custom_dims[i].uid == duid)
			{
				citem = calculation_custom_dims[i];
				break;
			}
		}
		
		if (citem)
		{
			mpanel.navigateApp(citem.uid, citem.type.toLowerCase(), citem.name, null, true, true, {
				editmode: me.writable,
				dmode: 1,
				dmode_cnt: citem,
				cubeuid: rcube.get("uid"),
				cubepath: rcube.get("nodepath"),
				callback: new IG$.callBackObj(me, function(citem) {
					rec.set("name", citem.name);
				})
			});
		}
	},
	
	setFilter: function(fitem) {
		var me = this,
			cube_tree = me.down("[name=cube_tree]");
		
		cube_tree.setFilter(fitem);
	},
	
	$getTreeData: function() {
		var me = this,
			cube_tree = me.down("[name=cube_tree]");
		
		return cube_tree.$getTreeData();
	},
	
	initComponent : function() {
		var me = this;
		
		me.addEvents("cube_changed");
								
		$s.apply(me, {
			// title: IRm$.r1("T_RPT_PIVOT"),
			header: false,
			
			items: [
				{
					xtype: "panel",
					// title: IRm$.r1("L_BOBJ"),
					border: 1,
					layout: {
						type: "vbox",
						align: "stretch"
					},
					items: [
						new IG$.naviTree({
							instance: me.instance,
							showtoolbar: false,
							cubebrowse: true,
							ddGroup: "_I$RD_G_",
							name: "cube_tree",
							layout: "fit",
							enabledrag: true,
							rootuid: "none",
							flex: 1,
							border: 0,
							_search: me.meta_type == "sql_report" ? false : true,
							meta_type: me.meta_type,
							rptptr: me.rptptr,
							hiddenItems: {
								cubemodel: 1
							},
							tools: [
								{
									xtype: "button",
									iconCls: "icon-toolbar-addsheet",
									//hidden: ig$.$l_ > 5,
									tooltip: IRm$.r1("B_ADD"),
									handler: function() {
										var me = this,
											rptptr = me.rptptr;
											
										rptptr.showReportOption(null, new IG$.callBackObj(me, function(ds_object) {
											var me = this,
												rop = me.reportoption,
												sop = me.sheetoption,
												filteroption = me.filteroption,
												i, bf = 0;
												
											for (i=0; i < rop._mc.cube_objects.length; i++)
											{
												if (rop._mc.cube_objects[i].uid == ds_object.uid)
												{
													bf = 1;
													break;
												}
											}
											
											if (!bf)
											{
												rop._mc.cube_objects.push(ds_object);
											}
											
											if (sop)
											{
												sop.model.cube_object = ds_object;
											}
											else if (filteroption && filteroption.model)
											{
												filteroption.model.cube_object = ds_object;
											}
											
											me.getCube(rop._mc.cube_objects);
										}), me.sheetoption, false, true);
									},
									scope: me
								}
							]
						}),
						{
							xtype: "gridpanel",
							ddGroup: "_I$RD_G_",
							enabledrop: false,
							enabledrag: true,
							height: 150,
							name: "custom_formula",
							hideHeaders: true,
							hidden: ig$.features["ig_p_cmt"] !== false || me.meta_type == "sql_report" || me.meta_type == "form_editor", //  || ig$.$l_ > 5, 
							columns: [
								{
									text: IRm$.r1("B_NAME"),
									dataIndex: "name",
									flex: 1
								},
								{
									xtype: "actioncolumn",
									width: 40,
									items: [
										{
											iconCls: "icon-grid-config",
											tooltip: "Config Item",
											handler: function (grid, rowIndex, colIndex) {
												var dt = grid.store.data.items[rowIndex],
													dtype;
												
												this.editCustomItem(dt);
											},
											scope: this
										},
										{
											iconCls: "icon-grid-delete",
											tooltip: "Remove Item",
											handler: function (grid, rowIndex, colIndex) {
												var me = this,
													dt = grid.store.data.items[rowIndex],
													rop = me.reportoption,
													calculation_custom_dims = rop._mc.calculation_custom_dims,
													i, duid = dt.get("uid");
												
												for (i=0; i < calculation_custom_dims.length; i++)
												{
													if (calculation_custom_dims[i].uid == duid)
													{
														calculation_custom_dims.splice(i, 1);
														break;
													}
												}
												
												grid.store.removeAt(rowIndex);
											},
											scope: this
										}
									]
								}
							],
							store: {
								fields: []
							},
							tbar: [
								{
									xtype: "displayfield",
									value: IRm$.r1("L_CUSTOM_FIELD")
								},
								"->",
								{
									xtype: "button",
									iconCls: "icon-toolbar-addsheet",
									tooltip: IRm$.r1("B_ADD"),
									menu: {
										xtype: "menu",
										items: [
											{
												text: IRm$.r1("D_CUSTOMMETRIC"),
												hidden: ig$.features["ig_n_cm"] !== false, 
												handler: function() {
													this.createItem("CustomMetric");
												},
												scope: this
											},
											{
												text: IRm$.r1("D_MEASURE"),
												hidden: ig$.features["ig_n_ms"] !== false, 
												handler: function() {
													this.createItem("Measure");
												},
												scope: this
											},
											{
												text: IRm$.r1("D_FORMULA"),
												hidden: ig$.features["ig_n_fm"] !== false, 
												handler: function() {
													this.createItem("FormulaMeasure");
												},
												scope: this
											}
										]
									}
								}
							]
						}
					]
				}
			]
		});
		
		if (me.meta_type == "sql_report")
		{
			this.items[0].tools = [
				{
					type: "refresh",
					handler: function() {
						var me = this,
							rop = me.reportoption, 
							meta_type = me.meta_type;
						
						if (meta_type == "sql_report")
						{
							me._load_columns(rop._mc.inlineview_sql_objects);
						}
					},
					scope: this
				}
			];
		}
		
		IG$.p$PivotBrws.superclass.initComponent.apply(me, arguments);
	}
});