IG$.r___ = {};

IG$.r___.registerTooltip = function(tobj, tcode) {
	if (!IG$.r___.C/*content*/)
	{
		$.ajax({
			type: "GET",
			url: "./data/tip.json" + "?uniquekey=" + IG$.getUniqueKey(), 
			dataType: "json",
			timeout: 10000,
			success: function(data) {
				IG$.r___.C/*content*/ = data;
				IG$.r___.registerTooltip(tobj, tcode);
			},
			error: function(e, status, thrown) {
			}
		});
	}
	else
	{
		var tdoc = IG$.r___.C/*content*/ ? IG$.r___.C/*content*/[tcode] : null;
		
		if (tdoc && window.Ext)
		{
			Ext.tip.QuickTipManager.register({
				target: tobj.getId(), // Target button's ID
				title: tdoc.title,  // QuickTip Header
				text: tdoc.html // Tip content  
			});
		}
	}
};

IG$.loadHelp = function(hcode, h) {
	if (!IG$.r___.bC/*content*/)
	{
		$.ajax({
			type: "GET",
			url: "./data/manual.json" + "?uniquekey=" + IG$.getUniqueKey(), 
			dataType: "json",
			timeout: 10000,
			success: function(data) {
				IG$.r___.bC/*content*/ = data;
				var tdoc = IG$.r___.bC/*content*/ ? IG$.r___.bC/*content*/[hcode] : null;
				
				if (tdoc)
				{
					h.t = tdoc.t;
					h.c = tdoc.h;
					h.show();
				}
				else
				{
					IG$.alertmsg("Error!", "Document for (" + hcode + ") is not prepared yet!", null, null, 1, "error");
				}
			},
			error: function(e, status, thrown) {
			}
		});
	}
	else
	{
		var tdoc = IG$.r___.bC/*content*/ ? IG$.r___.bC/*content*/[hcode] : null;
		
		if (tdoc)
		{
			h.t = tdoc.t;
			h.c = tdoc.h;
			
			h.show();
		}
		else
		{
			IG$.alertmsg("Error!", "Document for (" + hcode + ") is not prepared yet!", null, null, 1, "error");
		}
	}
}