IG$.chartSeries = $s.extend($s.window, {
	
	modal: true,
	region:'center',
	layout: {
		type: 'fit',
		align: 'stretch'
	},
	
	closable: false,
	resizable:false,
	width: 340,
	autoHeight: true,
	
	_init: function() {
		var me = this,
			seriestype = me.down("[name=seriestype]"),
			dl_marker = me.down("[name=dl_marker]"),
			dl_marker_type = me.down("[name=dl_marker_type]"),
			dl_marker_size = me.down("[name=dl_marker_size]"),
			dl_enable = me.down("[name=dl_enable]"),
			dl_linewidth = me.down("[name=dl_linewidth]"),
			dl_linetype = me.down("[name=dl_linetype]"),
			dl_position = me.down("[name=dl_position]"),
			rec = me.cell_record;
		
		seriestype.setValue(rec.get("seriestype"));
		dl_marker.setValue(rec.get("dl_marker"));
		dl_marker_type.setValue(rec.get("dl_marker_type"));
		dl_marker_size.setValue(rec.get("dl_marker_size"));
		dl_enable.setValue(rec.get("dl_enable"));
		dl_linewidth.setValue(rec.get("dl_linewidth") || 1);
		dl_linetype.setValue(rec.get("dl_linetype") || "");
		dl_position.setValue(rec.get("dl_position"));
		
		me.down("[name=dl_c_range]").setAllValues(rec.get("dl_c_range") || {}, true);
	},
	
	_confirm: function() {
		var me = this;
		
		me.seriestype = me.down("[name=seriestype]").getValue();
		me.dl_marker = me.down("[name=dl_marker]").getValue();
		me.dl_marker_type = me.down("[name=dl_marker_type]").getValue();
		me.dl_marker_size = me.down("[name=dl_marker_size]").getValue();
		me.dl_enable = me.down("[name=dl_enable]").getValue();
		me.dl_linetype = me.down("[name=dl_linetype]").getValue();
		me.dl_linewidth = "" + me.down("[name=dl_linewidth]").getValue();
		me.dl_position = me.down("[name=dl_position]").getValue();
		
		me.dl_c_range = {};
		me.down("[name=dl_c_range]").getAllValues(me.dl_c_range, true);
		
		me.callback && me.callback.execute(me);
		me.close();
	},
	
	initComponent : function() {
		var me = this;
		
		$s.apply(this, {
			
			title: IRm$.r1('T_CHART_SERIES'),
			items: [
				{
					xtype: "panel",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					padding: ig$.padding,
					defaults: {
						anchor: "100%"
					},
					items: [
						{
							xtype: "fieldset",
							title: IRm$.r1("L_SERIES"),
							defaultType: "textfield",
							items: [
								{
									name: "seriestype",
									xtype: "combobox",
									fieldLabel: IRm$.r1("L_SERIES_TYPE"),
									editable: false,
									valueField: "value",
									displayField: "name",
									queryMode: "local",
									autoSelect: true,
									store: {
										fields: [
											"name", "value"
										],
										data: [
											{name: IRm$.r1("B_DEFAULT"), value: ""},
											{name: IRm$.r1("L_CH_COLUMN"), value: "column"},
											{name: IRm$.r1("L_CH_LINE"), value: "line"},
											{name: IRm$.r1("L_CH_SPLINE"), value: "spline"},
											{name: IRm$.r1("L_CH_AREA"), value: "area"},
											{name: IRm$.r1("L_CH_BAR"), value: "Bar"},
											{name: IRm$.r1("L_CH_SPLINE_AREA"), value: "areaspline"},
											{name: IRm$.r1("L_CH_CUST_XLABEL"), value: "custxlabel"}
										]
									}
								},
								{
									name: "dl_linetype",
									xtype: "combobox",
									fieldLabel: IRm$.r1("L_LINE_TYPE"),
									editable: false,
									valueField: "value",
									displayField: "name",
									queryMode: "local",
									autoSelect: true,
									store: {
										fields: [
											"name", "value"
										],
										data: [
											{name: IRm$.r1("B_DEFAULT"), value: ""},
											{name: "Solid", value: "solid"},
											{name: "Dashed", value: "dashed"},
											{name: "Dotted", value: "dotted"},
											{name: "Hide", value: "hide"}
										]
									}
								},
								{
									name: "dl_linewidth",
									xtype: "numberfield",
									fieldLabel: IRm$.r1("L_LINE_WIDTH"),
									value: 1
								},
								{
									name: "dl_marker",
									xtype: "combobox",
									fieldLabel: IRm$.r1("L_MARKER"),
									editable: false,
									valueField: "value",
									displayField: "name",
									queryMode: "local",
									autoSelect: true,
									store: {
										fields: [
											"name", "value"
										],
										data: [
											{name: IRm$.r1("B_DEFAULT"), value: ""},
											{name: IRm$.r1("B_ENABLED"), value: "T"},
											{name: IRm$.r1("B_DISABLED"), value: "F"}
										]
									}
								},
								{
									name: "dl_marker_type",
									fieldLabel: IRm$.r1("L_MARKER_TYPE"),
									xtype: "combobox",
									queryMode: "local",
									displayField: "name",
									valueField: "value",
									editable: false,
									autoSelect: true,
									store: {
										xtype: "store",
										fields: [
											"name", "value"
										],
										data: [
											{name: IRm$.r1("B_DEFAULT"), value: ""},
											{name: IRm$.r1("L_M_CIRCLE"), value: "circle"},
											{name: IRm$.r1("L_M_RECT"), value: "rect"},
											{name: IRm$.r1("L_M_ROUND_RECT"), value: "roundRect"},
											{name: IRm$.r1("L_M_TRIANGLE"), value: "triangle"},
											{name: IRm$.r1("L_M_DIAMOND"), value: "diamond"},
											{name: IRm$.r1("L_M_PIN"), value: "pin"},
											{name: IRm$.r1("L_M_ARROW"), value: "arrow"}
										]
									}
								},
								{
									name: "dl_marker_size",
									fieldLabel: IRm$.r1("L_MARKER_SIZE"),
									xtype: "numberfield"
								},
								{
									name: "dl_enable",
									xtype: "combobox",
									fieldLabel: IRm$.r1("L_DATA_LABEL"),
									editable: false,
									valueField: "value",
									displayField: "name",
									queryMode: "local",
									autoSelect: true,
									store: {
										fields: [
											"name", "value"
										],
										data: [
											{name: IRm$.r1("B_DEFAULT"), value: ""},
											{name: IRm$.r1("B_ENABLED"), value: "T"},
											{name: IRm$.r1("B_DISABLED"), value: "F"}
										]
									}
								},
								{
									name: "dl_position",
									xtype: "combobox",
									fieldLabel: IRm$.r1("L_POSITION"),
									queryMode: "local",
									displayField: "name",
									valueField: "value",
									editable: false,
									autoSelect: true,
									store: {
										xtype: "store",
										fields: [
											"name", "value"
										],
										data: [
											{name: IRm$.r1("B_DEFAULT"), value: ""},
											{name: IRm$.r1("B_TOP"), value: "top"},
											{name: IRm$.r1("B_BOTTOM"), value: "bottom"},
											{name: IRm$.r1("B_INSIDE"), value: "inside"},
											{name: IRm$.r1("B_INSIDE") + " " + IRm$.r1("B_TOP"), value: "insideTop"},
											{name: IRm$.r1("B_INSIDE") + " " + IRm$.r1("B_BOTTOM"), value: "insideBottom"}
										]
									}
								}
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_RANGE"),
							defaultType: "textfield",
							name: "dl_c_range",
							items: [
								{
									xtype: "checkbox",
									fieldLabel: IRm$.r1("L_HIDDEN"),
									boxLabel: IRm$.r1("B_ENABLED"),
									name: "dl_c_hidden"
								},
								{
									xtype: "textfield",
									fieldLabel: IRm$.r1("L_MINIMUM"),
									name: "dl_c_min"
								},
								{
									xtype: "textfield",
									fieldLabel: IRm$.r1("L_MAXIMUM"),
									name: "dl_c_max"
								},
								{
									xtype: "fieldcontainer",
									anchor: "100%",
									fieldLabel: IRm$.r1("L_MIN_COLOR"),
									layout: {
										type: "hbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "textfield",
											name: "mincolor",
											width: 120
										},
										{
											xtype: "splitter"
										},
										{
											fieldLabel: "..",
											xtype: "splitbutton",
											menu: {
												showSeparator: false,
												items: [
													{
														xtype: "colorpicker",
														listeners: {
															select: function(cp, color) {
																var ctrl = this.down("[name=mincolor]");
																ctrl.setValue("#" + color);
															},
															scope: me
														}
													}, 
													"-"
												]
											}
										},
										{
											xtype: "container",
											flex: 1
										}
									]
								},
								{
									xtype: "fieldcontainer",
									anchor: "100%",
									fieldLabel: IRm$.r1("L_MID_COLOR"),
									
									layout: {
										type: "hbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "textfield",
											name: "midcolor",
											width: 120
										},
										{
											xtype: "splitter"
										},
										{
											fieldLabel: "..",
											xtype: "splitbutton",
											menu: {
												showSeparator: false,
												items: [
													{
														xtype: "colorpicker",
														listeners: {
															select: function(cp, color) {
																var ctrl = this.down("[name=midcolor]");
																ctrl.setValue("#" + color);
															},
															scope: me
														}
													}, 
													"-"
												]
											}
										},
										{
											xtype: "container",
											flex: 1
										}
									]
								},
								{
									xtype: "fieldcontainer",
									anchor: "100%",
									fieldLabel: IRm$.r1("L_MAX_COLOR"),
									
									layout: {
										type: "hbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "textfield",
											name: "maxcolor",
											width: 120
										},
										{
											xtype: "splitter"
										},
										{
											fieldLabel: "..",
											xtype: "splitbutton",
											menu: {
												showSeparator: false,
												items: [
													{
														xtype: "colorpicker",
														listeners: {
															select: function(cp, color) {
																var ctrl = this.down("[name=maxcolor]");
																ctrl.setValue("#" + color);
															},
															scope: me
														}
													}, 
													"-"
												]
											}
										},
										{
											xtype: "container",
											flex: 1
										}
									]
								}
							]
						}
					]
				}
			],
			buttons:[
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, 
				{
					text: IRm$.r1('B_CANCEL'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(tobj) {
					tobj._init();
				}
			}
		});
		
		IG$.chartSeries.superclass.initComponent.apply(this, arguments);
	}
});



IG$.chartPlotband = $s.extend($s.window, {
	
	modal: true,
	region:'center',
	layout: {
		type: 'fit',
		align: 'stretch'
	},
	
	closable: false,
	resizable:false,
	width: 380,
	autoHeight: true,
	
	callback: null,
	
	_init: function() {
		var me = this,
			ditem = me.ditem;
			
		if (ditem)
		{
			me.setAllValues(ditem._content);
		}
	},
	
	_confirm: function() {
		var me = this,
			ditem = me.ditem,
			has_error;
		
		if (ditem)
		{
			has_error = me.getAllValues(ditem._content);
		}
		
		if (!has_error)
		{
			me.callback && me.callback.execute(me.ditem);
			me.close();
		}
	},
	
	initComponent : function() {
		$s.apply(this, {
			defaults: {
				padding: ig$.padding
			},
			title: IRm$.r1('T_CHART_PLOTBAND'),
			items: [
				{
					xtype: "panel",
					layout: "anchor",
					defaults: {
						anchor: "100%"
					},
					padding: ig$.padding,
					items: [
						{
							xtype: "fieldset",
							title: IRm$.r1('T_CHART_PLOTBAND'),
							items: [
								{
									xtype: "textfield",
									name: "name",
									fieldLabel: IRm$.r1("B_NAME")
								},
								{
									name: "type",
									xtype: "combobox",
									fieldLabel: IRm$.r1("L_BAND_TYPE"),
									editable: false,
									valueField: "value",
									displayField: "name",
									queryMode: "local",
									autoSelect: true,
									store: {
										fields: [
											"name", "value"
										],
										data: [
											{name: "Line", value: "line"},
											{name: "Band", value: "band"},
											{name: "CurveFit", value: "curvefit"}
										]
									},
									listeners: {
										change: function(tobj) {
											var me = this,
												tval = tobj.getValue(),
												t_1 = me.down("[name=t_1]"),
												t_2 = me.down("[name=t_2]");
											
											t_1.setVisible(tval == "line" || tval == "band");
											t_2.setVisible(tval == "curvefit");
										},
										scope: this
									}
								},
								{
									xtype: "fieldcontainer",
									layout: "anchor",
									name: "t_1",
									hidden: true,
									items: [
										{
											xtype: "textfield",
											name: "value_1",
											fieldLabel: IRm$.r1("L_BAND_VALUE_1")
										},
										{
											xtype: "textfield",
											name: "value_2",
											fieldLabel: IRm$.r1("L_BAND_VALUE_2")
										},
										{
											xtype: "fieldcontainer",
											fieldLabel: IRm$.r1("L_BAND_COLOR"),
											layout: {
												type: "hbox"
											},
											items: [
												{
													xtype: "textfield",
													name: "color",
													width: 120
												},
												{
													xtype: "splitter"
												},
												{
													xtype: 'splitbutton',
													width: 30,
													menu: {
														showSeparator: false,
														items: [
															{
																xtype: "colorpicker",
																listeners: {
																	select: function(cp, color) {
																		var forecolor = this.down("[name=color]");
																		forecolor.setValue("#" + color);
																	},
																	scope: this
																}
															}, 
															'-'
														]
													}
												}
											]
										},
										{
											xtype: "combobox",
											name: "cf_lc",
											fieldLabel: IRm$.r1("L_CFIT_LC"),
											editable: false,
											valueField: "value",
											displayField: "name",
											queryMode: "local",
											autoSelect: true,
											store: {
												fields: [
													"name", "value"
												],
												data: [
													{name: "Solid", value: "Solid"},
													{name: "ShortDash", value: "ShortDash"},
													{name: "ShortDot", value: "ShortDot"},
													{name: "ShortDashDot", value: "ShortDashDot"},
													{name: "ShortDashDotDot", value: "ShortDashDotDot"},
													{name: "Dot", value: "Dot"},
													{name: "Dash", value: "Dash"},
													{name: "LongDash", value: "LongDash"},
													{name: "DashDot", value: "DashDot"},
													{name: "LongDashDot", value: "LongDashDot"},
													{name: "LongDashDotDot", value: "LongDashDotDot"}
												]
											}
										},
										{
											xtype: "numberfield",
											name: "borderwidth",
											fieldLabel: IRm$.r1("L_BAND_BORDER"),
											minValue: 0,
											maxValue: 10
										},
										{
											xtype: "checkbox",
											name: "isxaxis",
											fieldLabel: IRm$.r1("L_ON_X_AXIS"),
											boxLabel: IRm$.r1("B_ENABLED")
										}
									]
								},
								{
									xtype: "fieldcontainer",
									layout: "anchor",
									name: "t_2",
									hidden: true,
									items: [
										{
											name: "rtype",
											xtype: "combobox",
											fieldLabel: IRm$.r1("L_CFIT_TYPE"),
											editable: false,
											valueField: "value",
											displayField: "name",
											queryMode: "local",
											autoSelect: true,
											store: {
												fields: [
													"name", "value"
												],
												data: [
													{name: "Linear", value: "linear"},
													{name: "Polynomial", value: "polynomial"},
													{name: "Exponential", value: "exponential"},
													{name: "Logarithmic", value: "logarithmic"},
													{name: "Power", value: "power"}
												]
											},
											listeners: {
												change: function(tobj) {
													var me = this,
														tval = tobj.getValue(),
														order = me.down("[name=order]");
														
													order.setDisabled(tval != "polynomial");
												},
												scope: this
											}
										},
										{
											xtype: "numberfield",
											name: "order",
											disabled: true,
											fieldLabel: IRm$.r1("L_CFIT_PORD"),
											minValue: 2,
											maxValue: 5
										},
										
										{
											xtype: "checkbox",
											name: "showfitexp",
											fieldLabel: IRm$.r1("L_CFIT_FOR"),
											boxLabel: IRm$.r1("B_ENABLED")
										},
										{
											xtype: "numberfield",
											name: "cfitfcs",
											fieldLabel: IRm$.r1("L_CFIT_FCS"),
											minValue: 0,
											step: 0.1,
											value: 0
										},
										{
											xtype: "checkbox",
											name: "cfitallseries",
											fieldLabel: IRm$.r1("L_CFIT_AS"),
											boxLabel: IRm$.r1("B_ENABLED")
										},
										{
											xtype: "checkbox",
											name: "cfitshowsum",
											fieldLabel: IRm$.r1("L_CFIT_SS"),
											boxLabel: IRm$.r1("B_ENABLED")
										}
									]
								}
							]
						}
					]
				}
			],
			buttons:[
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, 
				{
					text: IRm$.r1('B_CANCEL'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(ui) {
					this._init();
				}
			}
		});
		
		IG$.chartPlotband.superclass.initComponent.apply(this, arguments);
	}
});