IG$.BC$base/*hadoop_dlg_base*/ = $s.extend($s.panel, {
	
	region:"center",
	layout: "fit",
			
	callback: null,
	
	init_f: function() {
		var me = this,
			job = me.job;
			
		if (job)
		{
			me.down("[name=dsname]").setValue(job.dsname);
			me.down("[name=dsdesc]").setValue(job.dsdesc);
			me.down("[name=dsignoreerror]").setValue(job.dsignoreerror);
			
			me.rL/*refreshLog*/();
		}
	},
	
	
	_confirm: function(ignore_callback) {
		var me = this,
			job = me.job;
			
		if (job)
		{
			job.dsname = me.down("[name=dsname]").getValue();
			job.dsdesc = me.down("[name=dsdesc]").getValue();
			job.dsignoreerror = me.down("[name=dsignoreerror]").getValue();
		}
		
		if (ignore_callback !== true)
		{
			me.callback && me.callback.execute(me.job);
			me.fireEvent("close_dlg", me);
		}
	},
	
	rL/*refreshLog*/: function() {
		var me = this,
			lreq = new IG$._rpc$();
		if (me.job && me.job.sid && me.s_hist)
		{
			lreq.init(me, 
				{
					ack: "hadoophelper",
					payload: {sid: me.job.sid},
					mbody: {option: "logcontent"}
				}, me, me.rs_rL/*refreshLog*/, false);
				
			lreq.send();
		}
	},
	
	rs_rL/*refreshLog*/: function(xdoc) {
		var me = this,
			tnode = IG$.XGetNode(xdoc, "/smsg"),
			tnodes = (tnode ? IG$.XGetChildNodes(tnode) : null),
			i, logs = [], l,
			grdloghist = me.down("[name=grdloghist]"),
			pdesc,
			duration, m, s, ms;
			
		if (tnodes)
		{
			for (i=0; i < tnodes.length; i++)
			{
				l = IG$.XGetAttrProp(tnodes[i]);
				l.pstatus = parseInt(l.pstatus);
				l.created_desc = IG$.formatDate(l.created);
				l.updated_desc = IG$.formatDate(l.updated);
				duration = Number(l.duration);
				duration = isNaN(duration) ? null : duration;
				if (duration != null)
				{
					m = Math.floor(duration / (60*1000));
					duration -= m * (60*1000);
					s = Math.floor(duration / (1000));
					duration -= s * (1000);
					ms = duration;
					l.duration = (m>0 ? m + "m " : "") + (s>0 ? s + "s " : "") + (ms>-1 ? ms + "ms" : "");
				}
				pdesc = "Unknown";
				switch (l.pstatus)
				{
				case 1:
					pdesc = "Running";
					break;
				case 10:
					pdesc = "Completed";
					break;
				case 20:
					pdesc = "Error: No result";
					break;
				case 21:
					pdesc = "Error: Dataformat mismatch";
					break;
				case 29:
					pdesc = "Error: Execution failed";
					break;
				}
				
				l.pstatus_desc = pdesc;
				logs.push(l);
			}
		}
		
		grdloghist.store.loadData(logs);
	},
	
	g1/*getLogDetail*/: function(lid) {
		var me = this,
			lreq = new IG$._rpc$();
		lreq.init(me, 
			{
				ack: "hadoophelper",
				payload: {lid: lid},
				mbody: {option: "logdetail"}
			}, me, me.rs_g1/*getLogDetail*/, false);
			
		lreq.send();
	},
	
	rs_g1/*getLogDetail*/: function(xdoc) {
		var me = this,
			tnode = IG$.XGetNode(xdoc, "/smsg"),
			tnodes = tnode ? IG$.XGetChildNodes(tnode) : null,
			errmsg,
			snode,
			msg, i, tmsg,
			haserr = false;
			
		if (tnodes)
		{
			for (i=0; i < tnodes.length; i++)
			{
				snode = IG$._I19/*getSubNode*/(tnodes[i], "errormessage");
				
				if (snode)
				{
					msg = IG$.XGetTextVal(snode);
					msg = Base64.decode(msg);
					haserr = true;
				}
				else
				{
					snode = IG$._I19/*getSubNode*/(tnodes[i], "message");
					if (snode)
					{
						msg = IG$.XGetTextVal(snode);
						msg = Base64.decode(msg);
					}
				}
				
				tmsg = (tmsg) ? tmsg + "\n" + msg : msg;
			}
			
			me.down("[name=logdetail]").setValue(tmsg);
						
			if (haserr == true)
			{
				IG$.alertmsg(ig$.appname, "One or more command failed. See log for detail", null, me, 1, "error");
			}
		}
	},
	
	GG1/*getMapClasses*/: function(field) {
		var me = this,
			dlgitemsel = new IG$.metaSelectDlg({
			instance: me.instance,
			visibleItems: 'javapackage;folder;javaclass',
			tree_options: {
				cubebrowse: false,
				rootuid: "/BusinessLogic",
				visibleItems: 'javapackage;folder;javaclass'
			},
			callback: new IG$.callBackObj(this, this.rs_GG1/*getMapClasses*/, field)
		});
		IG$.checkLogin(this, dlgitemsel);
	},
	
	rs_GG1/*getMapClasses*/: function(item, field) {
		var tname = "",
			cpath;
		
		if (item && item.nodepath)
		{
			cpath = item.nodepath;
			cpath = cpath.split("/");
			cpath.splice(0, 2);
			
			tname = cpath.join(".");
		}
		field.setValue(tname);
	},
	
	_pot_type_changed: function() {
		var me = this,
			potential_type = me.down("[name=potential_type]").getValue();
			g_p1 = me.down("[name=g_p1]"),
			g_p2 = me.down("[name=g_p2]");
		
		g_p1.show();
		g_p2.hide();
		
		switch (potential_type)
		{
		case "":
			break;
		case "CYCLE_LENGTH_SHIFT":
			g_p1.hide();
			break;
		}
	},
		
	initComponent : function() {
		var panel = this,
			bsitem = [],
			i;
		
		// panel.title = panel.title || IRm$.r1("T_BG_DS");
		panel.addEvents("close_dlg");
		
		bsitem.push({
			xtype: "fieldset",
			title: "Basic Option",
			layout: {
				type: "vbox",
				align: "stretch"
			},
			defaults: {
				labelPosition: "top"
			},
			items: [
				{
					xtype: "textfield",
					name: "dsname",
					fieldLabel: IRm$.r1("B_NAME")
				},
				{
					xtype: "textarea",
					name: "dsdesc",
					fieldLabel: IRm$.r1("B_DESC")
				},
				{
					xtype: "checkbox",
					name: "dsignoreerror",
					hidden: panel.hide_ierr ? true : false,
					fieldLabel: "Ignore Error",
					labelAlign: "left",
					boxLabel: "Ignore and continue"
				}
			]
		});
		
		if (panel.moption)
		{
			for (i=0; i < panel.moption.length; i++)
			{
				bsitem.push(panel.moption[i]);
			}
		}
		
		$s.apply(this, {
			items: [
				{
					xtype: "tabpanel",
					layout: "fit",
					items: [
						{
							xtype: "form",
							layout: {
								type: "vbox",
								align: "stretch"
							},
							title: "Configuration",
							autoScroll: true,
							items: bsitem
						},
						{
							xtype: "form",
							title: "History",
							hidden: panel.s_hist == 0,
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "fieldset",
									title: "Execute Log",
									layout: "fit",
									flex: 1,
									items: [
										{
											xtype: "gridpanel",
											name: "grdloghist",
											store: {
												xtype: "store",
												fields: [
													"sid", "lid", "jobtype", "pstatus", "created", "updated",
													"pstatus_desc", "created_desc", "updated_desc", "duration"
												]
											},
											columns: [
												{
													xtype: "gridcolumn",
													text: "Start time",
													flex: 1,
													dataIndex: "created_desc"
												},
												{
													xtype: "gridcolumn",
													text: "End time",
													flex: 1,
													dataIndex: "updated_desc"
												},
												{
													xtype: "gridcolumn",
													text: "Duration",
													dataIndex: "duration",
													flex: 1
												},
												{
													xtype: "gridcolumn",
													text: "Status",
													width: 120,
													dataIndex: "pstatus_desc"
												}
											],
											tbar: [
												{
													xtype: "button",
													text: "Refresh",
													handler: function() {
														var me = this;
														me.rL/*refreshLog*/();
													},
													scope: this
												}
											],
											listeners: {
												itemclick: function(view, record, item, index, e) {
													var lid = record.get("lid");
													
													if (lid)
													{
														this.g1/*getLogDetail*/(lid);
													}
												},
												scope: this
											}
										}
									]
								},
								{
									xtype: "fieldset",
									title: "Log Details",
									layout: "fit",
									flex: 2,
									items: [
										{
											xtype: "textarea",
											name: "logdetail"
										}
									]
								}
							]
						},
						{
							xtype: "panel",
							hidden: (panel.s_hist != 0),
							title: "Probability",
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "fieldcontainer",
									fieldLabel: "Relation Type",
									layout: "hbox",
									items: [
										{
											xtype: "combobox",
											name: "potential_type",
											labelWidth: 80,
											width: 200,
											queryMode: 'local',
											displayField: 'name',
											valueField: 'value',
											editable: false,
											autoSelect: true,
											store: {
												xtype: 'store',
												fields: [
													"name", "value"
												]
											},
											listeners: {
												change: function(tobj) {
													this._pot_type_changed();
												},
												scope: this
											}
										},
										{
											xtype: "button",
											text: "Reorder Potential"
										}
									]
								},
								{
									xtype: "gridpanel",
									hideHeaders: false,
									columnLines: true,
									name: "g_p1",
									editable: true,
									title: "",
									height: 400,
									viewConfig : {
										enableTextSelection : true,
										ForceFit : true,
										loadMask : true
									},
									flex: 1,
									store: {
										fields: ["name"]
									},
									columns: [
										{
											text: IRm$.r1("B_NAME"),
											dataIndex: "name",
											flex: 1
										},
										{
											text: IRm$.r1("B_VALUE"),
											dataIndex: "value",
											flex: 1
										}
									],
									listeners: {
										itemdblclick: function(tobj, rec, node, rindex, e, dataIndex) {
											var me = this,
												g_p1 = me.down("[name=g_p1]"),
												probability = me.$probability,
												table_result,
												colmap,
												hc,
												hr,
												cc;
											
											if (probability)
											{
												table_result = probability.table_result;
												colmap = table_result.colmap;
												hc = table_result.hc;
												hr = table_result.hr || 1;
												cc = colmap[dataIndex];
												
												if (cc > 0 && hc <= rindex)
												{
													g_p1.edit_cell(rec, rindex, dataIndex, {}, true, true);
												}
											}
											
											return false;
										},
										edit: function(tobj, data) {
											var me = this,
												rec = data.record,
												oldvalue = data.oldvalue,
												value = data.value,
												nvalue = Number(value),
												column = data.column,
												dataIndex = data.dataIndex,
												row = data.row,
												probability = me.$probability,
												table_result = probability.table_result,
												hc = table_result.hc,
												g_p1 = me.down("[name=g_p1]"),
												_prob_value_edit = me._prob_value_edit,
												crec,
												i;
											
											if (isNaN(nvalue))
											{
												// error for the value editing. should be numeric number
												rec.set(dataIndex, oldvalue);
											}
											else
											{
												_prob_value_edit.push({
													row: row,
													col: column
												});
												
												for (i=hc; i < g_p1.store.data.items.length; i++)
												{
													crec = g_p1.store.data.items[i];
													if (i != row)
													{
														var cc = 1 - nvalue;
														crec.set(dataIndex, cc);
														
														_prob_value_edit.push({
															row: i,
															col: column
														});
													}
												}
											}
										},
										scope: this
									}
								},
								{
									xtype: "gridpanel",
									hideHeaders: false,
									columnLines: true,
									name: "g_p2",
									hidden: true,
									title: "Edit Variance Potential",
									viewConfig : {
										enableTextSelection : true,
										ForceFit : true,
										loadMask : true
									},
									flex: 1,
									store: {
										fields: ["name"]
									},
									columns: [
										{
											text: "Name",
											dataIndex: "name",
											flex: 1
										},
										{
											text: "Value",
											dataIndex: "value",
											flex: 1,
											editor: {
												type: "number"
											}
										}
									]
								}
							]
						}
					]
				}
			],
			buttons:[
				"->",
				{
					text: IRm$.r1("B_CONFIRM"),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, {
					text: IRm$.r1("B_CANCEL"),
					handler:function() {
						// this.close();
						var me = this;
						me.fireEvent("close_dlg", me);
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(ui) {
					var panel = this;
					panel.init_f();
				}
			}
		});
		
		IG$.BC$base/*hadoop_dlg_base*/.superclass.initComponent.apply(this, arguments);
	}
});