/***********************************************************************
 * AppPageControl: Picture 
 */
 IG$.ctrlPicture = IG$.extend(IG$.ctrlBase, {
	type: "picture",
	initComponent: function() {
		var me = this;
		
		me.image = null;
		
		me.p.push(
			{name: "imagepath", type:"property", datatype: "string", "enum": "resources"},
			{name: "flexHeight", type: "property", datatype: "number", value: 0},
			{name: "minHeight", type: "property", datatype: "number", value: 0}
		);
		
		me.superclass.prototype.initComponent.call(me);
	},

	initDrawing: function() {
		var me = this;
		me.image = $('<img/>');
		me.image.appendTo(me.el$);
		
		me.superclass.prototype.initDrawing.call(me);
	},
	
	updateProperty: function(kname, value) {
		var me = this;
		
		switch (kname)
		{
		case "imagepath":
			if (value)
			{
				me.image.show();
				me.image.attr("src", ig$.servlet + "/resource?sreq=resource&_rcs_=" + value + "&_mts_=" + IG$._g$a);
			}
			else
			{
				me.image.hide();
			}
			break;
		}
	},
	
	invalidate: function() {
		var me = this,
			w = IG$.j$ext._w(me.html),
			h = IG$.j$ext._h(me.html);
		
		me.image && me.image.css({width: w + "px", height: h + "px"});
	}
});

IG$.controls.image = new IG$.ctrlPicture({}, null);
