IG$.sheetFilter = IG$.extend(IG$.ctrlBase, {
	type: "sheetfilter",
	initComponent: function() {
		var me = this;
		
		me.p.push(
			{name: "flexHeight", type: "property", datatype: "number", value: 0},
			{name: "minHeight", type: "property", datatype: "number", value: 0},
			{name: "report_control", type: "property", datatype: "string", vmode: 1},
			{name: "filter_id", type: "property", datatype: "string", vmode: 1},
			{name: "itemclick", type: "event"}
		);
		
		me.superclass.prototype.initComponent.call(me);
	},
	
	processEvent: function(evttype, obj) {
	},
	
	invalidate: function () {
		var me = this
	},
	
	applyApplication: function () {
	},
	initDrawing: function () {
		var me = this;

		me.html.addClass("igc_view_mode");
		
		me.viewer = new IG$.dynFilterView(me.instance, me.el$, null, me);
		me.viewer.init_f(true);
		me.tl$.hide();
		
		me.__pcinit();
	},
	updateProperty: function(kname, value) {
		var me = this;
		switch(kname)
		{
		case "report_control":
			me.__ivp();
			break;
		}
	},
	__ivp: function() {
		var me = this,
			property = me.property,
			report_control = property["report_control"],
			filter_id = property["filter_id"],
			rptctrl,
			i,
			dashboard = me.ctrl.dashboard,
			dctrl;
			
		if (me.dsmode || me.__pcinit_)
		{
			return;
		}
			
		if (report_control && dashboard && dashboard.ControlDict)
		{
			setTimeout(function() {
				var dctrl,
					dobj;
				dctrl = dashboard.ControlDict[report_control];

				if (dctrl && filter_id)
				{
					dobj = dctrl.control;
					if (dobj.negoFilter)
					{
						me.el$.empty();
						ubody = dobj.negoFilter(me, filter_id, new IG$.callBackObj(me, function(opt) {
							var ubody = opt.ubody;
							if (ubody && ubody.view)
							{
								ubody.view.contentarea.appendTo(me.el$);
								ubody.view.splash.appendTo(me.el$);

								me.ctrl.owner.validateSize();
							}
						}));
					}
				}
			}, 20);
		}
	}
});

IG$.controls.sheetfilter = new IG$.sheetFilter({}, null);