

/**
 * radiobox control
 */
IG$._FC_radiobox = $s.extend(IG$._baseFC, {
	objtype: "radiobox",
	s_codemap: 1,
	s_metric: 1,
	events: [
		{name: "change_val"}
	],
	create: function(container) {
		ui = $("<select multiple='multiple'></select>")
			.css({height: 80})
			.appendTo(container);
		ui.bind("change", function() {
			me.trigger("change_val", fitem.updateValues == true);
		});
	},
	setValue: function(values, cmap, svalues) {
		var me = this,
			ui = me.ui;
		ui.val(values);
	},
	updateValue: function(value) {
		var me = this,
			ui = me.ui,
			sval;
			
		sval = ui.val() || [];
		for (j=0; j < sval.length; j++)
		{
			if (sval[j] != "")
			{
				value.push({code: sval[j], value: sval[j]});
			}
		}
	},
	loadData: function(data) {
		var me = this,
			ui = me.ui,
			fmodel = me.fmodel,
			dp, aname = "", i;
			
		ui.empty();
		dp = ui.attr("options");
		if (fmodel.showallvalue)
		{
			if (fmodel.isnecessary)
			{
				aname = fmodel.aname || IRm$.r1("L_SELECT_VALUE");
			}
			else
			{
				aname = fmodel.aname || IRm$.r1("L_ALL_VALUE");
			}
			$("<option value=''>" + aname + "</option>").appendTo(ui);
		}
		for(i=0; i < data.length; i++)
		{
			// dp[i+1] = new Option(disp && disp.length > i ? disp[i] : data[i], data[i]);
			$("<option value='" + data[i].code + "'>" + (data[i].disp || data[i].code) + "</option>").appendTo(ui);
		}
		
		ui.trigger("change");
	},
	clear: function() {
		var me = this,
			ui = me.ui;
			
		ui.val([]);
		$("option:selected", ui).removeAttr("selected");
	}
});

IG$.$FCinst["radiobox"] = new IG$._FC_radiobox();