IG$.dlg_share = $s.extend($s.window, {
	width: 650,
	height: 500,
	layout: {
		type: "vbox",
		align: "stretch"
	},
	modal: true,
	
	_init: function() {
		var me = this,
			l_url = ig$.serveraddress || "",
			m_lnk = me.down("[name=m_lnk]");
			
		if (l_url.indexOf(";") > -1)
		{
			l_url = l_url.substring(l_url.indexOf(";") + 1);

			if (l_url.indexOf(";") > 0)
			{
				l_url = l_url.substring(0, l_url.indexOf(";"));
			}
			
			var n1 = l_url.indexOf("{"),
				n2 = l_url.indexOf("}", n1 + 1);
				
			while (n1 > -1 && n2 > n1)
			{
				var v = l_url.substring(n1+1, n2),
					v1;
					
				if (v == "uid")
				{
					v1 = me.uid;
				}
				else if (v == "mts")
				{
					v1 = IG$._g$a || "";
				}
				else
				{
					v1 = "";
				}
				
				l_url = l_url.substring(0, n1) + v1 + l_url.substring(n2 + 1);
				
				n1 = l_url.indexOf("{");
				n2 = l_url.indexOf("}", n1+1);
			}
		}
		else
		{
			if (l_url.charAt(l_url.length-1) != '/')
			{
				l_url += '/';
			}
			l_url += "launcher/viewer.jsp";
			
			if (l_url.indexOf("?") > -1)
			{
				l_url += "&";
			}
			else
			{
				l_url += "?";
			}
			
			l_url += "objid=" + me.uid
			
			l_url += "&mts=" + (IG$._g$a || "")
		}
		
		m_lnk.setValue(l_url);
		
		me._get_links();
	},
	
	_share_me: function() {
		var me = this,
			m_em = me.down("[name=m_em]"),
			m_msg = me.down("[name=m_msg]"),
			email = m_em.getValue(),
			msg = m_msg.getValue(),
			b_need_login = me.down("[name=b_need_login]"),
			p_lnk = me.down("[name=p_lnk]").getValue();
		
		m_em.clearInvalid();
		
		if (email)
		{
			var req = new IG$._rpc$(),
				addr = {
					recipient: email,
					message: msg,
					uid: me.uid,
					linkurl: p_lnk,
					is_public: b_need_login.getValue() ? "F" : "T"
				};
			IG$.confirmMessages(ig$.appname, IRm$.r1("M_CREATE_SHARE_URL"), function(e) {
				if (e == "yes")
				{
					req.init(me, 
						{
							ack: "sendmail",
							payload: {uid: me.uid, mtype: "share_item"},
							mbody: addr
						}, me, function(jdoc) {
							IG$.alertmsg(ig$.appname, IRm$.r1("M_SAVED"), null, null, 0, "success");
							
							me.down("[name=p_lnk]").setValue(jdoc.lurl);
							me._get_links();
						});
					req.send();
				}
			}, me, me);
		}
		else
		{
			m_em.markInvalid("Required!");
		}
	},
	
	_gen_link: function() {
		var me = this,		
			b_need_login = me.down("[name=b_need_login]"),
			req = new IG$._rpc$();
		
		IG$.confirmMessages(ig$.appname, IRm$.r1("M_CONFIRM_SHARE_URL"), function(e) {
			if (e == "yes")
			{
				req.init(me, 
					{
						ack: "sendmail",
						payload: {uid: me.uid, mtype: "share_link"},
						mbody: {is_public: b_need_login.getValue() ? "F" : "T"}
					}, me, function(jdoc) {
						if (jdoc)
						{
							me.down("[name=p_lnk]").setValue(jdoc.lurl);
							me._get_links();
						}
					});
				req.send();
			}
		}, me, me);
	},
	
	_get_links: function() {
		var me = this,		
			req = new IG$._rpc$();
		
		req.init(me, 
			{
				ack: "sendmail",
				payload: {uid: me.uid, mtype: "get_share_link"},
				mbody: {}
			}, me, function(jdoc) {
				var grd_shared = me.down("[name=grd_shared]");
				
				if (jdoc)
				{
					grd_shared.store.loadData(jdoc);
				}
			});
		req.send();
	},
	
	initComponent: function() {
		var me = this;
		
		$s.apply(me, {
			title: IRm$.r1("T_SHARE_SETTINGS"),
			padding: ig$.padding,
			items: [
				{
					xtype: "panel",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					items: [
						{
							xtype: "container",
							layout: "anchor",
							autoScroll: true,
							defaults: {
								anchor: "100%",
								labelPosition: "top"
							},
							items: [
								{
									xtype: "fieldset",
									title: IRm$.r1("L_EMBED_LINK"),
									layout: {
										type: "vbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "textarea",
											name: "m_lnk",
											fieldLabel: IRm$.r1("L_LINK_TO_SHARE"),
											readOnly: true,
											labelPosition: "top"
										},
										{
											html: IRm$.r1("M_SHARE_PAGE"),
											autoHeight: true
										}
									]
								},
								{
									xtype: "fieldset",
									title: IRm$.r1("L_SHARE_PUBLIC"),
									layout: {
										type: "vbox",
										align: "stretch"
									},
									defaults: {
										labelPosition: "top"
									},
									items: [
										{
											xtype: "textfield",
											name: "m_em",
											fieldLabel: IRm$.r1("L_PEOPLE"),
											emptyText: IRm$.r1("L_INPUT_EMAIL")
										},
										{
											xtype: "textarea",
											name: "m_msg",
											fieldLabel: IRm$.r1("L_EMAIL_MSG"),
											emptyText: IRm$.r1("L_EMPTY_MSG")
										},
										{
											html: IRm$.r1("M_EMAIL_DESC"),
											autoHeight: true
										},
										{
											xtype: "checkbox",
											name: "b_need_login",
											fieldLabel: IRm$.r1("L_LOGIN"),
											labelPosition: "left",
											boxLabel: IRm$.r1("L_NEED_LOGIN"),
											value: true
										},
										{
											xtype: "container",
											layout: {
												type: "hbox",
												align: "stretch"
											},
											items: [
												{
													xtype: "textarea",
													name: "p_lnk",
													readOnly: true,
													height: 120,
													flex: 1,
													labelPosition: "top",
													fieldLabel: IRm$.r1("L_PUBLIC_LINK_URL")
												},
												{
													xtype: "container",
													layout: {
														type: "vbox",
														align: "stretch"
													},
													items: [
														{
															xtype: "container",
															height: 20
														},
														{
															xtype: "button",
															text: IRm$.r1("B_GENERATE"),
															handler: function() {
																this._gen_link();
															},
															scope: this
														}
													]
												}
											]
										},
										{
											xtype: "fieldcontainer",
											layout: {
												type: "hbox",
												align: "stretch"
											},
											items: [
												{
													xtype: "container",
													flex: 1
												},
												{
													xtype: "button",
													text: IRm$.r1("B_SHARE"),
													handler: function() {
														this._share_me();
													},
													scope: this
												}
											]
										}
									]
								},
								{
									xtype: "fieldset",
									title: IRm$.r1("L_SHARE_HISTORY"),
									layout: {
										type: "vbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "textarea",
											fieldLabel: IRm$.r1("L_URL_OF_SHARE_OBJ"),
											labelPosition: "top",
											name: "h_url",
											height: 100
										},
										{
											xtype: "gridpanel",
											name: "grd_shared",
											height: 300,
											store: {
												fields: []
											},
											
											columns: [
												{
													text: IRm$.r1("B_DATE"),
													tdCls: "igc-td-link",
													dataIndex: "cdate"
												},
												{
													text: IRm$.r1("B_IS_PUBLIC"),
													xtype: "checkcolumn",
													dataIndex: "is_public",
													readOnly: true
												},
												{
													text: IRm$.r1("L_VISIT_COUNT"),
													dataIndex: "acc_count"
												},
												{
													text: IRm$.r1("L_LAST_VIEWED"),
													dataIndex: "ldate"
												},
												{
													xtype: "actioncolumn",
													width: 40,
													items: [
														{
															iconCls: "icon-grid-delete",
															handler: function(grid, rindex, cindex, rec) {
																if (rec.get("uid"))
																{
																	var me = this;
																	IG$.confirmMessages(ig$.appname, IRm$.r1("M_CONFIRM_DISABLE"), function(e) {
																		if (e == "yes")
																		{
																			var req = new IG$._rpc$(),
																				payloads = [],
																				i;
																			
																			req.init(me, 
																				{
																					ack: "sendmail",
																					payload: {
																						suid: rec.get("suid"),
																						uid: me.uid,
																						mtype: "remove_share_link"
																					},
																					mbody: {}
																				}, me, function(jdoc) {
																					var store = grid.store;
																					store.remove(rec);
																				});
																			req.send();
																		}
																	}, me, me);
																}
															},
															scope: this
														}
													]
												}
											],
											listeners: {
												cellclick: function(view, node, c, rec, rindex, e) {
													if (c == 0)
													{
														var me = this,
															h_url = me.down("[name=h_url]");
														
														h_url.setValue(rec.get("url"));
													}
												},
												scope: this
											}
										}
									]
								}
							]
						}
					]
				}
			],
			buttons: [
				{
					xtype: "button",
					text: IRm$.r1("B_CLOSE"),
					handler: function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(tobj) {
					tobj._init();
				}
			}
		});
		
		IG$.dlg_share.superclass.initComponent.call(this);
	}
});