/***********************************************************************
 * AppPageControl: Combobox 
 */
 IG$.ctrlComboBox = IG$.extend(IG$.ctrlBase, {
	type: "combobox",
	md: 0,
	initComponent: function() {
		var me = this;
		me.p.push(
			{name: "fieldlabel", type: "property", datatype: "string"},
			{name: "labelwidth", type: "property", datatype: "number", value: 80},
			{name: "isnecessary", type: "property", datatype: "boolean"},
			{name: "showSelectAll", type: "property", datatype: "boolean"},
			{name: "selectAllText", type: "property", datatype: "string", value: "L_ALL_VALUE"},
			{name: "emptyText", type: "property", datatype: "string", value: "L_SELECT_VALUE"},
			{name: "text", type: "property", datatype: "string"},
			{name: "hierarchy", type: "property", datatype: "string"},
			{name: "change", type: "event"}
		);
		
		me.combobox = null;
		me.items = [];
		
		me.superclass.prototype.initComponent.call(me);
	},
	
	initDrawing: function () {
		var me = this,
			browser = window.bowser,
			fid = me._get_id(),
			ui = $("<div class='ig-db-combo-cnt form-outline'></div>")
				.appendTo(me.el$),
			applicationItem = me.applicationItem,
			property = me.property,
			sctrl,
			cbutton;
		
		cbutton = $("<div class='ig-db-combo-btn'></div>").appendTo(me.el$);
		
		ui.addClass("form-outline");
		me.tl$ && me.tl$.hide();
		me.mp$dv = me.createTextField(ui, me.property.fieldLabel);
		lbl$ = me.lbl$ = $(".mdc-floating-label", me.mp$dv); // .appendTo(me.el$);
		me.mp$ = mdc.textField.MDCTextField.attachTo(me.mp$dv);

		sctrl = $("input", me.mp$dv);
		sctrl.__c = true;
		sctrl.bind("input", function(e) {
			e.stopPropagation();
			e.stopImmediatePropagation();
			e.preventDefault();
			return false;
		});
		sctrl.bind("keydown", function(e) {
			if (e.key == "Escape")
			{
				me.mp$.value = "";
			}
		});
		sctrl.bind("click", function(e) {
			$(this).select();
		});
		
		var api_search = function(response, keyword) {
			var req = new IG$._rpc$(),
				meta_type = "valueinfo",
				address = [],
				cnt = {
					items: [],
					option: "ValueInfo"
				},
				hfilter,
				kfilter,
				fmodel = fitem.model,
				codemapping = fmodel.codemapping;
				
			if (fitem.itemtype == "prompt")
			{
				if (codemapping && codemapping.uid)
				{
					address.push({
						uid: codemapping.uid,
						type: fmodel.type,
						rptid: codemapping.uid
					});
					
					cnt.items.push({
						uid: codemapping.uid,
						cmap: codemapping,
						hfilter: hfilter
					});
				}
			}
			else
			{
				address.push({
					name: fmodel.name,
					uid: fmodel.uid,
					objtype: objtype,
					nodepath: fmodel.nodepath,
					rptid: fmodel.uid,
					sql_id: fmodel.sql_id
				});
				
				cnt.items.push({
					uid: fmodel.uid,
					cmap: codemapping,
					sql_id: fmodel.sql_id,
					hfilter: hfilter
				});
			}
			
			hfilter = me.form.checkHFilter(me);
			
			if (keyword.indexOf("%") < 0)
			{
				keyword += "%";
			}
			
			kfilter = {
				ftype: "condition",
				operator: "LIKE",
				fields: [
					address[0]
				],
				values: [
					{code: keyword, value: keyword}
				]
			};
			
			kfilter.fields[0].type = "";
			
			if (!hfilter)
			{
				hfilter = [kfilter];
			}
			else
			{
				hfilter.push(kfilter);
			}
			
			cnt.items[0].hfilter = hfilter;
				
			req.init(me, 
				{
					ack: "olapservice",
					payload: address,
					mbody: cnt,
					meta_type: meta_type
				}, me, function(jdoc) {
					if (jdoc.erroritems && jdoc.erroritems.length)
					{
						$.each(jdoc.erroritems, function(i, eitem) {
							IG$.ShowErrorMessage(eitem, me, null);
						});
						return;
					}
					
					var mchild = IG$.parseValueList(jdoc.value_results),
						i, sdp = [],
						dval,
						data = mchild[0].data,
						d;
					
					for(i=0; i < data.length; i++)
					{
						d = data[i];
						sdp.push({label: (d.disp || d.code), value: d.code});
					}
					
					me.kdp = sdp;
					response(sdp);
				}, function(jdoc) {
				});
			req.send();
		}
		
		sctrl.autocomplete({
			minLength: 0,
			sortResults: false,
			sortable: false,
			source: function(request, response) {
				var reqval = request.term,
					eval = reqval.split(/,\s*/),
					sdp = me.sdp;
				if (sdp)
				{
					reqval = eval.pop();
					
					me.kdp = null;
					
					if (reqval && sdp.length > 190)
					{
						api_search(response, reqval);
					}
					else
					{
						response($.ui.autocomplete.filter(sdp, reqval));
					}
				}
			},
			focus: function(e, ui) {
				return false;
			},
			select: function(e, mobj) {
				var svalue = mobj.item;
				
				if (!svalue.value)
				{
					if (property.showSelectAll)
					{
						me.mp$.value = "";
						ui.trigger("change");
					}
				}
				else
				{
					me.mp$.value = svalue.label;
					
					me._svalues = [
						{
							code: svalue.value,
							text: svalue.label
						}
					];
					ui.trigger("change");
				}
				
				if (browser.msie)
				{
					sctrl.blur();
				}
				return false;
			},
			open: function(e, mobj) {
				sctrl.__c = false;
			},
			close: function(e, mobj) {
				sctrl.__c = false;
				setTimeout(function() {
					sctrl.__c = true;
					if (browser.msie)
					{
						sctrl.blur();
					}
				}, 1200);
			}
		});
		
		sctrl.bind("keydown", function(e) {
			if (e.keyCode === $.ui.keyCode.TAB) 
			{
				sctrl.__c = true;
				
				var vmenu = $(this).autocomplete("widget").menu;
				if (vmenu.active)
				{
					e.preventDefault();
				}
			}
			else if (e.keyCode === $.ui.keyCode.ENTER)
			{
				var i,
					m = 0,
					l = me.mp$.value.toLowerCase(), 
					v,
					sdp = me.sdp,
					kdp = me.kdp,
					kdp_i,
					sdp_i;
				
				if (sdp && sdp.length && l)
				{
					v = l.length;
					
					for (i=0; i < sdp.length; i++)
					{
						sdp_i = sdp[i];
						if (sdp_i.label.substring(0, v).toLowerCase() == l)
						{
							me._svalues = [
								{
									code: sdp_i.value,
									text: sdp_i.label
								}
							];
							me.mp$.value = sdp_i.label;
							ui.trigger("change");
							m = 1;
							break;
						}
					}
					
					if (!m && kdp)
					{
						for (i=0; i < kdp.length; i++)
						{
							kdp_i = kdp[i];
							if (kdp_i.label.substring(0, v).toLowerCase() == l)
							{
								me._svalues = [
									{
										code: kdp_i.value,
										text: kdp_i.label
									}
								];
								me.mp$.value = kdp_i.label;
								ui.trigger("change");
								m = 1;
								break;
							}
						}
					}
				}
				if (m)
				{
					sctrl.autocomplete("close");
					sctrl.__c = true;
				}
			}
		});
		
		$(cbutton).bind("click", function(e) {
			e.stopImmediatePropagation();
			e.stopPropagation();
			e.preventDefault();
			
			if (sctrl.__c)
			{
				sctrl.__c = false;
				sctrl.autocomplete("search", ""); // filter value need to initialized
				sctrl.focus();
			}
			else
			{
				sctrl.__c = true;
				sctrl.autocomplete("close");
			}
		});
		
		ui.bind("change", function() {
			var bchanged = true,
				pkey = "__pval" + k,
				tval = me.mp$.value,
				sctrl_sel,
				sctrl_sel_code = "",
				i, placeholder = sctrl.attr("placeholder"),
				sdp = me.sdp,
				sdp_i;
			
			if (sdp && sdp.length)
			{
				for (i=0; i < sdp.length; i++)
				{
					sdp_i = sdp[i];
					
					if (placeholder && tval == placeholder)
					{
						continue;
					}
					else if (sdp_i.value == tval || sdp_i.label == tval)
					{
						sctrl_sel =
							{
								code: sdp_i.value,
								text: sdp_i.text || sdp_i.label
							};
						sctrl_sel_code = sctrl_sel.code;
						break;
					}
				}
			}
			
			if (me[pkey] == sctrl_sel_code)
			{
				bchanged = false;
			}
			
			if (bchanged)
			{
				me[pkey] = sctrl_sel_code;
				me.clearInvalid();
				
				if (applicationItem.type == "CodeMap")
				{
					me.value = [];
					// me.form.updateFilterValue(me);
					
					if (me.value && me.value.length && me.value[0].code)
					{
						var nvalue = me.value[0].code;
						setTimeout(function() {
							me.form._upd_vs_value.call(me.form, nvalue);
						}, 10);
					}
					return false;
				}
				
				if (me.property.isnecessary)
				{
					!sctrl_sel_code && me.markInvalid("required");
				}
				
				me.trigger("change", me.updateValues == true);
			}
		});

		me.superclass.prototype.initDrawing.call(me);
	},
	invalidate: function () {
	},
	
	commit: function() {
		var me = this;
	},
	
	applyDataSet: function(value) {
		var me = this,
			cols = value.v.cols,
			data = value.v.data,
			i, dp = [],
			p,
			mp$ = me.mp$;
		
		for (i=0; i < data.length; i++)
		{
			p = {
				code: data[i][cols[0].name],
				text: data[i][cols[cols.length > 1 ? 1 : 0].name]
			};
			
			dp.push(p);
		}
		
		me.loadData(dp);
	},
	
	updateProperty: function(kname, value) {
		var me = this,
			property = me.property;
		
		switch (kname)
		{
		case "text":
			me.mp$.value = value;
			break;
		case "label_names":
		case "value_names":
		case "name_delimiter":
			clearTimeout(me._vtimer);
			me._vtimer = setTimeout(function() {
				me._setData();
			}, 20);
			break;
		case "selectAllText":
			if (!property.isnecessary)
			{
				value = value && value.substring(0, 2) == "L_" ? IRm$.r1(value) : value;
				me.mp$.placeholder = value;
			}
			break;
		case "emptyText":
			if (property.isnecessary || property.selectAllText == false)
			{
				value = value && value.substring(0, 2) == "L_" ? IRm$.r1(value) : value;
				me.mp$.placeholder = value;
			}
			break;
		}
	},
	
	getSelectionData: function(itemname) {
		var me = this,
			mp$ = me.mp$,
			tval = mp$.value,
			placeholder = mp$.placeholder,
			sdp = me.sdp, sdp_i,
			i, 
			sval = [];
		
		if (tval && me._svalues && me._svalues.length && me._svalues[0].text == tval)
		{
			if (!placeholder || (placeholder && tval != placeholder))
			{
				sval = me._svalues;
			}
		}
		else if (tval && sdp && sdp.length)
		{
			for (i=0; i < sdp.length; i++)
			{
				sdp_i = sdp[i];
				if (placeholder && tval == placeholder)
				{
					continue;
				}
				else if (sdp_i.value == tval || sdp_i.label == tval)
				{
					sval.push(
						{
							code: sdp_i.value,
							text: sdp_i.text || sdp_i.label
						}
					);
					break;
				}
			}
		}

		return sval;
	},
	
	_setData: function() {
		var me = this,
			result = {
				data: []
			},
			i, delim, values, labels,
			property = me.property, m,
			rdata = result.data;
			
		labels = property.label_names || "";
		values = property.value_names || "";
		delim = property.name_delimiter || ";";
		
		labels = labels.split(delim);
		values = values.split(delim);
		
		m = Math.max(labels.length, values.length);
		
		for (i=0; i < m ; i++)
		{
			rdata.push({
				code: values[i] || labels[i],
				text: labels[i] || values[i]
			});
		}
			
		me.loadData(result);
	},
		
	loadData: function(result) {
		var me = this,
			property = me.property,
			i,
			sdp = [],
			p,
			sctrl = me.mp$,
			tval = sctrl.value,
			l, bf,
			aname;

		me._svalues = [];

		if (property.isnecessary == false && property.showSelectAll)
		{
			aname = property.selectAllText;
			aname = aname && aname.substring(0, 2) == "L_" ? IRm$.r1(aname) : aname;
			sdp.push({label: aname, value: ""});
		}
		
		for (i=0; i < result.data.length; i++)
		{
			p = result.data[i];
			l = (p.disp || p.code);
			if (tval && tval == l)
			{
				bf = true;
			}
			sdp.push({label: l, value: p.code});
		}

		if (!bf)
		{
			sctrl.value = "";
		}

		me.sdp = sdp;
		sctrl.trigger && sctrl.trigger("change");
	},
	sel: function(r) {
		var me = this,
			m, mp$ = me.mp$,
			st = mp$.store,
			i;
			
		if (typeof(r) == "undefined")
		{
			m = mp$.value;
		}
		else
		{
			if (st.data.items[r])
			{
				mp$.value = st.data.items[r].get("code");
			}
			else
			{
				for (i=0; i < st.data.items.length; i++)
				{
					if (st.data.items[i].get("code") == r)
					{
						mp$.value = r;
						break;
					}
				}
			}
		}
		
		return m;
	}
});

IG$.controls.combobox = new IG$.ctrlComboBox({}, null);