/**
 * @module widget/sheetfiltercomp
 * @desc Sheet Filtering Component
 *
 * @property {string} docid - docking object id 
 */
IG$.sheetfiltercomp = function(node) {
	var me = this,
		i,
		fitem;
	
	node = me.model = node || {};
	
	me.docid = node.docid;
	
	$s.defaults(node, {
		objtype: node.objtype || "PANEL",
		layoutinfo: {},
		filter_items: [],
		filter_options: {},
		edrill: true
	});
		
	$s.defaults(node.filter_options, {
		showbutton: true,
		buttonname: "{L_BTN_SEARCH}",
		f_bx_name: "{L_D_EXCEL}",
		f_t_dir: "left",
		// showbutton: false,
		viewtype: "row",
		brow: 0,
		columnsize: 1,
		rowsize: 1,
		// buttonname: null,
		f_b_desc: null,
		f_b_scr: null,
		showrefresh: true
	});
	
	me.tab_option = {};
	
	if (node.version != "1.0")
	{
		switch (node.version)
		{
		default:
			if (node.objtype == "FILTER")
			{
				$.each(node.filter_items, function(i, fitem) {
					fitem.colspan = (fitem.colspan || 1) * 2;
				});
			}
			break;
		}
	}
	
	node.version = "1.0";
};

IG$.sheetfiltercomp.prototype = {
	
};
