/**
 * @module widget/rfText
 * @desc Report Text Control
 *
 * @property {string} docid - docking object id
 * @property {div} container - html container
 * @property {model} sheetoption - widget option
 * @property {object} $report_view - report viewer pointer
 */
IG$.rfText = function (instance, container, sop, rpt) {
	var me = this;
	
	me.instance = instance;
	me.container = container;
	me.sheetoption = sop;
	
	me.updateValues = true;
	
	me.$report_view = rpt;
	
	me.$init();
};

IG$.rfText.prototype = {
	$init: function() {
		var me = this,
			carea = $("<div class='idv-pnl-html-cnt'></div>").appendTo(me.container);
		me.c1 = carea;
		me.contentarea = $("<div class='idv-pnl-html'></div>").appendTo(carea);
		me.setText();
	},
	
	removeObj: function() {
	},
	
	/**
	 * validate item
     * @memberof module:widget/rfText
	 */
	validateItems: function() {
		this.setText();
	},
	
	setSize: function(w, h) {
		var me = this,
			c1 = me.c1;
		
		IG$.j$ext._w(c1, w);
		IG$.j$ext._h(c1, h);
	},
	
	/**
	 * setText
     * @memberof module:widget/rfText
	 */
	setText: function() {
		var me = this,
			tvalue,
			finfo = me.finfo,
			tvalues = [],
			mvalues = [],
			mvalue,
			t,
			start = 0,
			end = 0,
			mpos,
			mvalue,
			mat, rvalue,
			i, j, b,
			so = me.sheetoption;
		
		tvalue = Base64.decode(so.model.htmlcontent || so.model.content || "");
		mpos = tvalue.indexOf("{", start);
		
		while (mpos > -1 && end < tvalue.length)
		{
			end = tvalue.indexOf("}", mpos);
			if (end > -1)
			{
				tvalues.push({t: tvalue.substring(start, mpos), m: 0});
				tvalues.push({t: tvalue.substring(mpos+1, end), m: 1});
			}
			else
			{
				end = start;
				tvalues.push({t: tvalue.substring(start, end), m: 0});
			}
			start = end+1;
			mpos = tvalue.indexOf("{", start);
		}
		
		tvalues.push({t: tvalue.substring(start, tvalue.length), m: 0});
		
		for (i=0; i < tvalues.length; i++)
		{
			t = tvalues[i];
			if (t.m == 1)
			{
				mat = t.t.match(/\[(.*?)\]/g);
				if (mat && mat.length > 0)
				{
					b = finfo ? true : false;
					
					if (finfo)
					{
						for (j=0; j < mat.length; j++)
						{
							rvalue = mat[j].replace(/[\[\]]/g, "");
							if (finfo[rvalue])
							{
								t.t = t.t.replace(new RegExp("\\[" + rvalue + "\\]", "g"), finfo[rvalue].data.join(", ") || "");
							}
							else
							{
								b = false;
								break;
							}
						}
					}
					
					if (b == true)
					{
						mvalues.push(t.t);
					} 
				}
				else
				{
					mvalues.push("{" + t.t + "}");
				}
			}
			else
			{
				mvalues.push(t.t);
			}
		}
		mvalue = mvalues.join("");
		me.contentarea.html(mvalue);
		
		tvalue = Base64.decode(so.model.jscript || "");
		
		var cls_id = me.cls_id;
		
		if (!cls_id)
		{
			if (tvalue)
			{
				try
				{
					ig$._txt_jscript = ig$._txt_jscript || 0;
					cls_id = 'cls_txt_' + (++ig$._txt_jscript);
					var dyn = new IG$.cDynScript(cls_id, 0),
						script = "ig$['" + cls_id + "'] = { init: function(owner, html) {\n" + tvalue + "\n}}";
						
					dyn.loadScript(script);
				}
				catch (e)
				{
					void 0;
					IG$.ShowError("Error on dynamic script loader", null, null, {errstack: e.stack});
				}
				
				me.cls_id = cls_id;
			}
		}
		
		if (cls_id && ig$[cls_id])
		{
			if (ig$[cls_id].init)
			{
				try
				{
					ig$[cls_id].init.call(me, me, me.contentarea);
				}
				catch (e)
				{
					void 0;
					IG$.ShowError("Error on dynamci script init call!", null, null, {errstack: e.stack});
				}
			}
			else
			{
				IG$.ShowError("init function need to be defined on the script!");
			}
		}
	},
	
	updateFilterContent: function(finfo) {
		var me = this;
		me.finfo = finfo;
		me.setText();
	}
};
