IG$.c$TblTree = $s.extend($s.treepanel, {
	columns: [
		{
			xtype: 'treecolumn',
			header: 'Name',
			dataIndex: 'disp',
			flex: 1
		}
	],
	appendNodeElement: function(pnode, item)
	{
		if(pnode.numNodeNames == undefined){
			pnode.numNodeNames = 1;
		}
		else{
			pnode.numNodeNames++;
		}
		
		var Model = this.store.model;
		
		var record = new Model(item);
		record.leaf = item.leaf;
		record.raw = item;
		pnode.data.leaf = false;
		pnode.appendChild(record);
			
		return record;
	},
	
	viewConfig: {
		plugins: {
			ptype: 'gridviewdragdrop',
			dragGroup: 'cubeDDGroup',
			dropGroup: 'cubeEDDGroup',
			enableDrag: true,
			enableDrop: false,
			listeners: {
				drop: function(node, data, dropRec, dropPosition) {
					var dropOn = dropRec ? ' ' + dropPosition + ' ' + dropRec.get('name') : ' on empty view';
				}
			}
		}
	},
	
	reqTable: function(node) {
		var panel = this,
			nodepath = node.get("nodepath"),
			nodeuid = node.get("uid"),
			ltype = node.get("type"),
			b_view = (ltype == "InlineView"),
			req = new IG$._rpc$(),
			ack = "25",
			pload, cnt;
		
		pload = {address: (nodeuid || nodepath), option: "StoredContent"};
		cnt = {option: "folder", readcontent: "T"};
		
		req.init(panel, 
			{
				ack: ack,
				payload: pload,
				mbody: cnt
			}, panel, function(jdoc) {
				var me = this,
					tnode = jdoc && jdoc.length ? jdoc[0] : null,
					snodes, i, tb, tables = [];
			
				if (tnode && tnode.children)
				{
					snodes = tnode.children;
					
					for (i=0; i < snodes.length; i++)
					{
						tb = snodes[i].content;
						tb.checked = false;
						tb.leaf = true;
						tb.allowDrag = true;
						
						if (panel.cmode == 1)
						{
							tb.disp = tb.alias && tb.alias != tb.name ? tb.alias + "(" + tb.name + ")" : tb.name;
						}
						else
						{
							tb.disp = tb.name;
						}
						
						node.appendChild(tb);
					}
				}
			}, false);
		req.send();
	},

	initComponent : function() {
		// call parent
		$s.apply(this, {
			store: {
				/*proxy: {
					type: 'memory'
				},
				*/
				store: "treestore",
				fieldSort: false,
				fields: [
					"name", "alias", "nodepath", "datasize", "selected", "tablename", "type", "uid", "disp", "seq",
					"datatype", "fieldname", "mapto", "sqlfield", "fieldid",
					"sequence", "uniquekey", "mcuid"
				],
				root: {
					name: 'CubeModel Tables',
					disp: "CubeModel Tables",
					address: '/'
				}
			},
			collapseFirst:false,
			singleExpand: false,
			nodekey: {},
			listeners: {
				/*
				itemclick: function(view, record, item, index, e)
				{
					// this.treeEditor.triggerEdit(record, item);
					// record.beginEdit();
				},
				*/
				checkchange: function(node, checked) {
					if (node.hasChildNodes() == true)
					{
						for (i=0; i < node.childNodes.length; i++)
						{
							node.childNodes[i].set("checked", checked);
						}
						
						node.expand();
					}
				},
				beforeitemexpand: function(node, eopts) {
					var me = this,
						ltype = node.get("type"),
						mtype;
					
					if ((ltype == "Table" || ltype == "InlineView") && node.hasChildNodes())
					{
						mtype = node.childNodes[0].get("type");
						
						if (mtype == "ml_tb")
						{
							node.removeChild(node.childNodes[0]);
							me.reqTable(node);
						}
					}
				},
				scope: this
			}
		});
		
		IG$.c$TblTree.superclass.initComponent.apply(this, arguments);
	  }
});